package africa.growtogether.platform.ewe.task; import java.time.Instant; import java.util.*; import org.springframework.data.jpa.repository.JpaRepository;
interface WorkflowTaskRepository extends JpaRepository<WorkflowTask,UUID>{Optional<WorkflowTask> findByIdAndTenantId(UUID id,UUID tenantId);List<WorkflowTask> findAllByInstanceIdAndTenantIdOrderByCreatedAtAsc(UUID instanceId,UUID tenantId);List<WorkflowTask> findAllByTenantIdAndAssigneeUserIdAndTaskStatusInOrderByCreatedAtDesc(UUID tenantId,UUID user,List<TaskStatus> states);List<WorkflowTask> findAllByTenantIdAndEscalationAtBeforeAndTaskStatusIn(UUID tenantId,Instant time,List<TaskStatus> states);}
interface WorkflowTaskEventRepository extends JpaRepository<WorkflowTaskEvent,UUID>{List<WorkflowTaskEvent> findAllByTaskIdOrderByOccurredAtAsc(UUID taskId);}
interface WorkflowRoutingRuleRepository extends JpaRepository<WorkflowRoutingRule,UUID>{List<WorkflowRoutingRule> findAllByWorkflowDefinitionIdAndTenantIdAndTaskKeyAndActiveTrueOrderByPriorityAsc(UUID definitionId,UUID tenantId,String taskKey);}
